Text.text:
{
                  path: 'FixationDate',
                  type: 'sap.ui.model.odata.type.DateTimeOffset',
                  constraints: { precision: 7 },
                  formatOptions: { pattern: 'dd/MM/yyyy' }
                }

{
                  path: 'FixationVolume',
                  type: 'sap.ui.model.odata.type.Double',
                  formatOptions: { decimals: 3, decimalSeparator: ',', groupingEnabled: true, groupingSeparator: '.' }
                }

{
                  path: 'FixationPrice',
                  type: 'sap.ui.model.odata.type.Double',
                  formatOptions: { decimals: 8, decimalSeparator: ',', groupingEnabled: true, groupingSeparator: '.' }
                }

{
                  path: 'FreightCost',
                  type: 'sap.ui.model.odata.type.Double',
                  formatOptions: { decimals: 2, decimalSeparator: ',', groupingEnabled: true, groupingSeparator: '.' }
                }

{
                  path: 'FinancialDueDate',
                  type: 'sap.ui.model.odata.type.DateTimeOffset',
                  constraints: { precision: 7 },
                  formatOptions: { pattern: 'dd/MM/yyyy' }
                }

{
                  path: 'ApprovedAt',
                  type: 'sap.ui.model.odata.type.DateTimeOffset',
                  constraints: { precision: 7 },
                  formatOptions: { pattern: 'dd/MM/yyyy HH:mm' }
                }
